600	function Stat({
601	  label,
602	  value,
603	  icon,
604	}: {
605	  label: string;
606	  value: string | number;
607	  icon?: React.ReactNode;
608	}) {
609	  return (
610	    <div className="text-center min-w-0">
611	      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
612	        {icon}
613	        {label}
614	      </p>
615	      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
616	    </div>
617	  );
618	}
619	
620	function ItemRow({
621	  item,
622	  onMarcarManual,
623	}: {
624	  item: ChegadaItem;
625	  onMarcarManual: () => void;
626	}) {
627	  const recebido = Number(item.quantidade_recebida || "0") || 0;
628	  const solicitado = item.quantidade_solicitada || 0;
629	  const enviado = Number(item.quantidade_enviada || "0") || 0;
630	  const pct = solicitado > 0 ? Math.min(100, Math.round((recebido / solicitado) * 100)) : 0;
631	  const status: "vazio" | "parcial" | "completo" | "excesso" =
632	    recebido === 0
633	      ? "vazio"
634	      : recebido > solicitado
635	        ? "excesso"
636	        : recebido >= solicitado
637	          ? "completo"
638	          : "parcial";
639	  const ring =
640	    status === "completo"
641	      ? "border-emerald-500/40 bg-emerald-500/5"
642	      : status === "excesso"
643	        ? "border-amber-500/40 bg-amber-500/5"
644	        : status === "parcial"
645	          ? "border-[#57715B]/30 bg-[#57715B]/5"
646	          : "border-white/30 dark:border-white/10";
647	  const bg =
648	    status === "completo"
649	      ? "bg-emerald-500"
650	      : status === "excesso"
651	        ? "bg-amber-500"
652	        : status === "parcial"
653	          ? "bg-[#57715B]"
654	          : "bg-zinc-300 dark:bg-zinc-700";
655	  return (
656	    <div className={cn("rounded-xl border-2 p-3", ring)}>
657	      <div className="flex items-start justify-between gap-2 mb-1.5">
658	        <div className="min-w-0 flex-1">
659	          <p className="text-sm font-semibold leading-tight truncate flex items-center gap-2">
660	            {status === "completo" && (
661	              <CheckCircle2 className="w-4 h-4 text-emerald-600 flex-shrink-0" />
662	            )}
663	            {status === "excesso" && (
664	              <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
665	            )}
666	            <span className="truncate">{item.nome_produto}</span>
667	          </p>
668	          <p className="text-[11px] text-muted-foreground mt-0.5">
669	            Pedido <b>{solicitado}</b> un · Expedido <b>{enviado || 0}</b> un
670	            {item.recebida_via && (
671	              <span
672	                className={cn(
673	                  "ml-2 inline-block px-1.5 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider",
674	                  item.recebida_via === "bip"
675	                    ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-300"
676	                    : "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-300",
677	                )}
678	              >
679	                {item.recebida_via}
680	              </span>
681	            )}
682	          </p>
683	        </div>
684	        <div className="flex items-center gap-2 flex-shrink-0">
685	          <span
686	            className={cn(
687	              "text-sm font-bold tabular-nums",
688	              status === "completo"
689	                ? "text-emerald-700"
690	                : status === "excesso"
691	                  ? "text-amber-700"
692	                  : "text-foreground",
693	            )}
694	          >
695	            {recebido}/{solicitado}
696	          </span>
697	          <Button
698	            data-mia-action="marcar-manual"
699	            size="sm"
700	            variant="outline"
701	            className="h-8 gap-1 text-[11px] border-[#57715B]/20 hover:bg-[#57715B]/10"
702	            onClick={onMarcarManual}
703	          >
704	            <Hand className="w-3 h-3" /> Manual
705	          </Button>
706	        </div>
707	      </div>
708	      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
709	        <div
710	          className={cn("h-full rounded-full transition-all duration-500", bg)}
711	          style={{ width: `${pct}%` }}
712	        />
713	      </div>
714	    </div>
715	  );
716	}
